import json
R=r'C:\Users\admin\OneDrive\dev\ltsgo'
P={}
for l in open(R+r'\texts\goncharov-pallada\passages.jsonl',encoding='utf8'):
    d=json.loads(l);P[d['seq']]=d
def rel(n): return open(R+rf'\texts\goncharov-pallada\related\{n}\text.txt',encoding='utf8').read()
norm=lambda s:' '.join(s.split())
def check(src,q):
    t=P[src]['body'] if isinstance(src,int) else rel(src)
    assert norm(q) in norm(t), (src,q)
    assert len(q.split())<=25,(q)
S_LH=[{'title':'NLB Infopedia: Gaston Dutronquoy / London Hotel','url':'https://eresources.nlb.gov.sg/infopedia/articles/SIP_1263_2007-07-06.html','quote':'(пересказ) с марта 1844 London Hotel — в бывшем Singapore Hotel на Эспланаде'},
      {'title':'Wikipedia: Gaston Dutronquoy','url':'https://en.wikipedia.org/wiki/Gaston_Dutronquoy','quote':'(пересказ) 1839 Commercial Square, 1841 Coleman St, 1844 Esplanade'}]
S_NY=[{'title':'Блог: 長崎奉行所西役所跡','url':'https://access21-co.xsrv.jp/shigekikou/archives/15195','quote':'嘉永６年（1853）、筒井政憲らがロシア使節プチャーチンを引見したのも本役所でした'},
      {'title':'obpen.com: 川路聖謨の対露交渉','url':'http://www.obpen.com/essay/20160319_01.html','quote':'12月14日: 長崎奉行所西役所にて、昼食を兼ねての初顔合わせ'}]
E=[]
def add(city,name,kind,person,seq,q,dates,status,addr_then=None,addr_now=None,lat=None,lon=None,wd=None,surv='unknown',now=None,sources=None,notes=None):
    check(seq,q)
    E.append(dict(book='goncharov-pallada',city=city,name_then=name,kind=kind,person=person,
      passage_seq=seq if isinstance(seq,int) else None,
      related=None if isinstance(seq,int) else f'texts/goncharov-pallada/related/{seq}/text.txt',
      book_quote=q,dates=dates,address_then=addr_then,address_now=addr_now,lat=lat,lon=lon,wikidata=wd,
      survives=surv,now_what=now,status=status,sources=sources or [],notes=notes))
